// src/Component/CompanyJobs.jsx
import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { fetchCompanyJobs, deleteJob, updateJob } from "../Features/JobSlice";
import "../Styles/CompanyJobs.css";

const CompanyJobs = () => {
  const dispatch = useDispatch();

  // state من السلايس
  const { companyJobs, isLoading } = useSelector((state) => state.jobs);

  const [editingIndex, setEditingIndex] = useState(null);
  const [editedJob, setEditedJob] = useState({});

  // Load jobs for company
  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem("loggedUser"));
    if (!saved?.email) return;
    dispatch(fetchCompanyJobs(saved.email));
  }, [dispatch]);

  // ===========================
  // EDIT HANDLERS
  // ===========================
  const handleEdit = (index) => {
    setEditingIndex(index);
    setEditedJob(companyJobs[index]);
  };

  const handleSave = () => {
    dispatch(updateJob(editedJob));
    setEditingIndex(null);
  };

  const handleCancel = () => {
    setEditingIndex(null);
  };

  const handleDelete = (id) => {
    if (window.confirm("Delete this job?")) {
      dispatch(deleteJob(id));
    }
  };

  if (isLoading) return <p className="loading">Loading jobs...</p>;

  return (
    <div className="companyjobs-page">
      <h1 className="companyjobs-title">
        My <span className="accent">Posted Jobs</span>
      </h1>

      {companyJobs.length === 0 ? (
        <p className="no-jobs">No jobs posted yet.</p>
      ) : (
        companyJobs.map((job, index) => (
          <div key={job._id} className="job-card">
            {editingIndex === index ? (
              <div className="edit-section">
                <label>Job Title</label>
                <input
                  type="text"
                  value={editedJob.jobTitle}
                  onChange={(e) =>
                    setEditedJob({ ...editedJob, jobTitle: e.target.value })
                  }
                />

                <label>Description</label>
                <textarea
                  value={editedJob.description}
                  onChange={(e) =>
                    setEditedJob({ ...editedJob, description: e.target.value })
                  }
                />

                <label>Skills</label>
                <textarea
                  value={editedJob.skills}
                  onChange={(e) =>
                    setEditedJob({ ...editedJob, skills: e.target.value })
                  }
                />

                <div className="edit-buttons">
                  <button className="btn-save" onClick={handleSave}>
                    Save
                  </button>
                  <button className="btn-cancel" onClick={handleCancel}>
                    Cancel
                  </button>
                </div>
              </div>
            ) : (
              <>
                <div className="job-header">
                  <h3>{job.jobTitle}</h3>
                  <span className="rate">
                    {job.rate} OMR • {job.rateType}
                  </span>
                </div>

                <p className="org-name">{job.organization}</p>
                <p className="desc">{job.description}</p>
                <p className="skills">Skills: {job.skills}</p>

                <div className="job-actions">
                  <button
                    className="btn-edit"
                    onClick={() => handleEdit(index)}
                  >
                    Edit
                  </button>

                  <button
                    className="btn-delete"
                    onClick={() => handleDelete(job._id)}
                  >
                    Delete
                  </button>

                  <button
                    className="btn-applicants"
                    onClick={() =>
                      window.location.assign(`/applicants-job?jobId=${job._id}`)
                    }
                  >
                    Applicants
                  </button>
                </div>
              </>
            )}
          </div>
        ))
      )}
    </div>
  );
};

export default CompanyJobs;
